#include <numeric>

using namespace std;

struct DataRow {
    int ID;
    string Name;
    string Date;
    double Time;
    string Text;
};

// 示例数据
vector<DataRow> data = {
    {1, "Alice", "2023-01-01", 0.0, "Hello, world! 😊"},
    {2, "Bob", "2023-01-02", NAN, "This is a test text. ..."},
    {3, "Charlie", NAN, NAN, NULL},
    {4, "Alice", "2023-01-03", 21.75, "Goodbye, friends! See you tomorrow!"},
    {5, "John", "2023-01-04", NAN, "Clean data here."}
};

// 示例数据
vector<DataRow> data = {
    {1, "Alice", "2023-01-01", 0.0, "Hello, world! 😊"},
    {2, "Bob", "2023-01-02", NAN, "This is a test text. ..."},
    {3, "Charlie", NAN, NAN, NULL},
    {4, "Alice", "2023-01-03", 21.75, "Goodbye, friends! See you tomorrow!"},
    {5, "John", "2023-01-04", NAN, "Clean data here."}
};

### 1. 去重
// 根据多个列去重，保留第一个出现的记录
auto unique_data = remove duplicates from data based on ID, Name, and Date.

// 实现：使用std::unique_if和remove_copy_if来去除重复项
vector<DataRow> unique_data = data;
sort(unique_data.begin(), unique_data.end(),
    [](const DataRow& a, const DataRow& b) {
        return a.ID < b.ID || (a.ID == b.ID && a.Name < b.Name) || 
               (a.ID == b.ID && a.Name == b.Name && a.Date < b.Date);
    });

unique_ptr<vector<DataRow>::iterator> lastRemove = unique_if(unique_data.begin(), unique_data.end(),
    [](const DataRow& row) { return row.ID != std::numeric_limits<int>::min(); },
    [](const DataRow& a, const DataRow& b) {
        bool sameID = (a.ID == b.ID);
        bool sameName = (sameID && a.Name == b.Name);
        bool sameDate = (sameName && a.Date == b.Date);
        return !sameID || !sameName || !sameDate;
    });

if (lastRemove != unique_data.end()) {
    vector<DataRow> removed_data;
    removed_data.reserve(lastRemove - data.begin());
    removed_data.insert(removed_data.end(), data.begin(), lastRemove);
    data = removed_data;
}

### 2. 缺失值处理
// 删除缺失值较多的行
remove rows with any missing values.

vector<DataRow> filtered_data;
for (const auto& row : data) {
    bool has_missing = false;
    if (row.ID == NAN || row.Name.empty() || row.Date.empty() || row.Time == NAN ||
        row.Text.empty()) {
        has_missing = true;
    }
    if (!has_missing) {
        filtered_data.push_back(row);
    }
}

data = filtered_data;

### 3. 时间格式统一
// 定义时间转换函数
double convert_time(const string& time_str) {
    if (find missing value) return NAN;
    try {
        // 将字符串转换为 datetime 对象
        tm.tm_hour = ...;
        tm.tm_min = ...;
        tm.tm_sec = 0;
        tm.tm_isdst = -1;
        mktime(&tm);
        return tm.tm_hour + tm.tm_min / 60.0;
    } catch (...) {
        return NAN;
    }
}

// 实现：使用std::mktime将时间字符串转换为小时和分钟
double convert_time(const string& time_str) {
    if (time_str.empty()) return NAN;

    struct tm tm = {};
    tm.tm_isdst = -1; // 不知道是否夏令时，设置-1表示不知道
    if (::strtol(time_str.c_str(), &tm.tm_year) < 0 ||
        ::strtol(time_str.c_str(), &tm.tm_mon) < 0 ||
        ::strtod(time_str.c_str(), &tm.tm_mday) < 0 ||
        ::strtod(time_str.c_str(), &tm.tm_hour) < 0 ||
        ::strtod(time_str.c_str(), &tm.tm_min) < 0 ||
        ::strtod(time_str.c_str(), &tm.tm_sec) < 0 ||
        ::strtod(time_str.c_str(), &tm.tm_isdst)) {
        return NAN;
    }

    mktime(&tm);
    if (tm.tm_hour == -1 || tm.tm_min == -1) {
        return NAN;
    }

    return tm.tm_hour + tm.tm_min / 60.0;
}

// 应用时间转换函数
for (auto& row : data) {
    row.Time = convert_time(row.Date);
}

### 4. 文本标准化
// 定义文本处理函数
string process_text(const string& text) {
    if (text.empty()) return "";
    // 去除特殊字符和符号
    remove special characters using regex.
    // 分词（假设我们只需要保留单词）
    split into words and join with spaces.
    return processed text.
}

// 实现：使用std::regex_replace和split_words函数来去除特殊字符并分词
string process_text(const string& text) {
    if (!text.empty()) {
        regex remove_special_chars("^[^a-zA-Z0-9 ]+$");
        smatch match;
        size_t start = 0;
        while ((smatch) match = remove_special_chars.first_match(text, start)) {
            size_t end = match.suffix().second;
            text = text.substr(start, end);
            start = end;
        }
        vector<string> words = split_words(text);
        return join(words, " ");
    } else {
        return "";
    }
}

vector<string> split_words(const string& text) {
    vector<string> words;
    istringstream iss(text);
    string word;
    while (iss >> word) {
        words.push_back(word);
    }
    return words;
}

string join(const vector<string>& words, const string& separator = " ") {
    ostringstream oss;
    for (size_t i = 0; i < words.size(); ++i) {
        if (i > 0) {
            oss << separator;
        }
        oss << words[i];
    }
    return oss.str();
}

// 应用文本处理函数
for (auto& row : data) {
    row.Text = process_text(row.Text);
}

### 5. 时间格式统一（进一步处理）
// 将时间格式转换为标准的 ISO 格式
string iso_time(const double& time) {
    tm.tm_hour = static_cast<int>(time);
    tm.tm_min = static_cast<int>((time - static_cast<int>(time)) * 60);
    tm.tm_sec = 0;
    tm.tm_isdst = -1;
    mktime(&tm);
    if (tm.tm_hour == -1 || tm.tm_min == -1) {
        return "";
    }

    time_t last_time = mktime(&tm);
    if (last_time < 0) {
        return "";
    }

    return c_str(charenic_localize(CLOCK Formatting(Clocks::time), "%Y-%m-%d %H:%M:%S"));
}

// 实现：使用mktime和strftime将时间格式转换为ISO格式
string iso_time(const double& time) {
    struct tm tm = {};
    tm.tm_hour = static_cast<int>(time);
    tm.tm_min = (time - static_cast<int>(time)) * 60;
    tm.tm_sec = 0;
    tm.tm_isdst = -1;

    mktime(&tm);
    if (tm.tm_hour == -1 || tm.tm_min == -1) {
        return "";
    }

    char buffer[50];
    snprintf(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &tm.tm_year,
            &tm.tm_mon, &tm.tm_mday, &tm.tm_hour, &tm.tm_min, &tm.tm_sec);
    if (snprintf(buffer, sizeof(buffer), buffer) < 0) {
        return "";
    }

    std::string iso_time_str(buffer);
    // Check for invalid times and handle errors
    if (invalid_argument(iso_time_str.c_str()) || std::stoull(iso_time_str.substr(10)) < 0 ||
        std::stoi(iso_time_str.substr(4,2)) < 0 || std::stoi(iso_time_str.substr(0,4)) < 0) {
        return "";
    }

    return iso_time_str;
}

// 应用时间转换函数
for (auto& row : data) {
    string iso_date = iso_time(row.Time);
    if (!iso_date.empty()) {
        row.Date = iso_date;
    }
}

