    }

    void set_entry_to_null(ChatLogEntry& entry) {
        entry.customer_id = -1;
        entry.timestamp = "";
        entry.text = "null";
    }

    string standardize_time(const string& timestamp) const {
        if (!is_string(timestamp)) return timestamp;

        time_t mktime(&timestamp);
        return mktime.tm_hourofday + ":" + to_string(mktime.tm_minofhour) + ": ...;
    }

    string remove_special_characters(const string& text) const {
        // Remove special characters using regex
        return regex_replace(text, "[^a-zA-Z0-9]", "");
    }

    vector<string> segment_words(const string& text) const {
        // Simple word segmentation for demonstration.
        vector<string> words;
        size_t start = 0;
        while (start < text.size()) {
            size_t end = start + 10; // Arbitrary chunk size
            substring(text, start, end - start);
            advance(start, end - start);
        }
        return words;
    }

    string join_segmented_words(const vector<string>& segments) const {
        if (segments.empty()) return "";
        ostringstream oss;
        oss << segments[0];
        for (size_t i = 1; i < segments.size(); ++i) {
            oss << " " << segments[i];
        }
        return oss.str();
    }

